# Tanakh's consonants before the append (the CLAIMS list). DRY mode (`--dry`): every run and claim checked, failures printed with the
# verse's consonants, nothing written. Appends to World/step9/effect_vocabulary.yaml as TEXT under `effects:`; idempotent; the NEW list
# is CHECKED AGAINST THE REGISTRY first (S2's lesson: a clashing name is skipped in silence).
import sqlite3, yaml, re, sys
ROOT = _ROOT
DRY = '--dry' in sys.argv
db = sqlite3.connect('file:%s/Data/tanakh.sqlite?mode=ro' % ROOT, uri=True)
BARE, POINT, TAN = {}, {}, {}
for bk, ch, vs, he in db.execute("SELECT v.book, v.chapter, v.verse, w.he FROM words w JOIN verses v ON w.verse_id=v.id ORDER BY v.book, v.chapter, v.verse, w.idx"):
    TAN.setdefault((bk, ch, vs), []).append(re.sub(r'[֑-ׇ/]', '', he))
    if bk == 'Gen':
        BARE.setdefault((ch, vs), []).append(re.sub(r'[֑-ׇ/]', '', he))
        POINT.setdefault((ch, vs), []).append(''.join(c for c in he if c != '/' and not (0x0591 <= ord(c) <= 0x05AF)))
def seats(tok): return sorted(k for k, ws in BARE.items() if tok in ws)
def run_seats(run):
    ws = run.split(); return sorted(k for k, vv in BARE.items() if any(vv[i:i+len(ws)] == ws for i in range(len(vv) - len(ws) + 1)))
def ttok(tok): return sorted(k for k, ws in TAN.items() if tok in ws)
def trun(run):
    ws = run.split(); return sorted(k for k, vv in TAN.items() if any(vv[i:i+len(ws)] == ws for i in range(len(vv) - len(ws) + 1)))
FAIL = []
def H(ch, vs, run, en):
    ws, want = BARE[(ch, vs)], run.split()
    idx = [i for i in range(len(ws) - len(want) + 1) if ws[i:i + len(want)] == want]
    if not idx:
        FAIL.append(('RUN NOT IN VERSE', ch, vs, run, ' '.join(ws))); return '?'
    return '%s (%s — Gen %d:%d)' % (' '.join(POINT[(ch, vs)][idx[0]:idx[0] + len(want)]), en, ch, vs)
